#!/usr/bin/env python3
"""Realism audit 1.2.3 ("questions"): a fresh set of player lines, written without reading player_questions.json.

Each row: text, channel, realm, class, level, topic, kind, must (facts a good reply holds), wrong (facts that make it wrong),
flags: s = silence is fine, g = the repo's data cannot give the true answer (hand-judged), n = said to the responder by name,
       h = hand-judged only (any fitting human reply is good).
"""
import json
import sys
from pathlib import Path

PLACES = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))['places']
NAMES = {'alb': 'Aldwyn', 'mid': 'Brannoc', 'hib': 'Siobhan'}
REALM = {'a': 'alb', 'm': 'mid', 'h': 'hib'}
CAP = {'alb': 'camelot', 'mid': 'jordheim', 'hib': 'tir na nog'}


def hunt(realm, level):
    """Places of the realm (and the shared ones) whose usual levels hold the level, give or take 3; wrong: 8+ off or another realm."""
    good, bad = [], []
    for p in PLACES:
        lv = p.get('levels')
        if not lv or p['type'] in ('capital',):
            continue
        names = [p['key']] + p.get('aliases', [])
        if p['realm'] in (realm, '*') and lv[0] - 3 <= level <= lv[1] + 3:
            good += names
        elif p['realm'] not in (realm, '*') or level < lv[0] - 8 or level > lv[1] + 8:
            bad += names
    return sorted(set(good)), sorted(set(bad) - set(good))


def lv(key):
    p = next(p for p in PLACES if p['key'] == key)
    a, b = p['levels']
    return [rf're:\b{a}\b.{{0,14}}\b{b}\b', rf're:\b{a}\+', rf're:\b{b}\b']


ROWS = []


def q(text, ch, realm, cls, level, topic, kind='question', must=None, wrong=None, flags=''):
    r = REALM[realm]
    if 'n' in flags:
        text = text.replace('{n}', NAMES[r]).replace('{nl}', NAMES[r].lower())
    row = dict(text=text, channel=ch, realm=r, cls=cls, level=level, intent=topic, kind=kind,
               must_any=list(must or []), wrong_any=list(wrong or []))
    if 's' in flags:
        row['silence_ok'] = True
    if 'g' in flags:
        row['data_gap'] = True
    if 'h' in flags:
        row['hand'] = True
    if 'n' in flags:
        row['to'] = NAMES[r]
    row['bracket'] = '1' if level < 5 else '5' if level < 10 else '10' if level < 20 else '20' if level < 35 else '35' if level < 50 else '50'
    ROWS.append(row)


def H(text, ch, realm, cls, level, flags=''):
    g, b = hunt(REALM[realm], level)
    q(text, ch, realm, cls, level, 'hunt', 'question', g, b, flags)


F, G, T, S = 'faction', 'group', 'tell', 'say'
CAPS = lambda r: [CAP[REALM[r]]] + (['tnn'] if r == 'h' else [])
TRAIN = lambda r: CAPS(r) + ['trainer']

